import { readFile, writeFile, mkdir } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const mode = process.argv[2] || 'apply';
const read = async p => (await readFile(path.join(root, p), 'utf8')).replace(/\r\n?/g, '\n');
const write = async (p, s) => { await mkdir(path.dirname(path.join(root, p)), { recursive: true }); await writeFile(path.join(root, p), s.endsWith('\n') ? s : `${s}\n`, 'utf8'); };
const replaceOnce = (s, from, to, label) => {
  const first = s.indexOf(from);
  if (first < 0) throw new Error(`Missing anchor: ${label}`);
  if (s.indexOf(from, first + from.length) >= 0) throw new Error(`Ambiguous anchor: ${label}`);
  return s.slice(0, first) + to + s.slice(first + from.length);
};
const replaceRegexOnce = (s, re, to, label) => {
  const matches = [...s.matchAll(new RegExp(re.source, re.flags.includes('g') ? re.flags : `${re.flags}g`))];
  if (matches.length !== 1) throw new Error(`${label}: expected one match, found ${matches.length}`);
  return s.replace(re, to);
};

